package com.bank.search.analysis;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

// Models a standard analyzer: char filter -> tokenizer -> token filters.
public class Analyzer {
    private static final List<String> STOP_WORDS = List.of("the", "a", "an", "to", "for");

    public List<String> analyze(String text) {
        // 1. char filter: drop punctuation. 2. tokenize on whitespace.
        String cleaned = text.replaceAll("[^a-zA-Z0-9 ]", " ");
        return Arrays.stream(cleaned.split("\\s+"))
                .map(String::toLowerCase)                 // token filter: lowercase
                .filter(t -> !t.isBlank())
                .filter(t -> !STOP_WORDS.contains(t))     // token filter: stop words
                .collect(Collectors.toList());
    }
}
