package com.bank.search.index;

import com.bank.search.analysis.Analyzer;
import java.util.*;

// Maps each term -> sorted set of document ids (a postings list).
public class InvertedIndex {
    private final Map<String, TreeSet<String>> postings = new HashMap<>();
    private final Analyzer analyzer = new Analyzer();

    // Index a document: analyze its text, add its id to each term's postings.
    public void add(Document doc) {
        for (String term : analyzer.analyze(doc.getText())) {
            postings.computeIfAbsent(term, k -> new TreeSet<>()).add(doc.getId());
        }
    }

    // Find doc ids containing ALL query terms (AND semantics).
    public Set<String> search(String query) {
        List<String> terms = analyzer.analyze(query);
        if (terms.isEmpty()) return Set.of();
        Set<String> result = new TreeSet<>(postings.getOrDefault(terms.get(0), new TreeSet<>()));
        for (int i = 1; i < terms.size(); i++) {
            result.retainAll(postings.getOrDefault(terms.get(i), new TreeSet<>()));
        }
        return result;
    }
}
