package com.bank.search.shard;

import com.bank.search.index.Document;
import com.bank.search.index.InvertedIndex;
import java.util.Set;

// Each shard is a complete, independent inverted index over a subset of docs.
public class Shard {
    private final int shardId;
    private final InvertedIndex index = new InvertedIndex();

    public Shard(int shardId) { this.shardId = shardId; }

    public void add(Document doc) { index.add(doc); }
    public Set<String> search(String query) { return index.search(query); }
    public int getShardId() { return shardId; }
}
