package com.bank.search.engine;

import com.bank.search.index.Document;
import com.bank.search.shard.Shard;
import java.util.*;
import java.util.logging.Logger;

// Routes docs to shards by hashing the id, fans out queries, merges results.
public class SearchEngine {
    private static final Logger log = Logger.getLogger(SearchEngine.class.getName());
    private final List<Shard> shards = new ArrayList<>();

    public SearchEngine(int numShards) {
        for (int i = 0; i < numShards; i++) shards.add(new Shard(i));
    }

    // Routing: shard = hash(id) % numShards — spreads documents evenly.
    public void index(Document doc) {
        int shardId = Math.floorMod(doc.getId().hashCode(), shards.size());
        shards.get(shardId).add(doc);
        log.fine(() -> "doc " + doc.getId() + " routed to shard " + shardId);
    }

    // Fan-out: query every shard in parallel, merge the matching ids.
    public Set<String> search(String query) {
        Set<String> merged = new TreeSet<>();
        for (Shard s : shards) {
            Set<String> hits = s.search(query);
            if (!hits.isEmpty()) {
                log.info(() -> "shard " + s.getShardId() + " matched " + hits);
            }
            merged.addAll(hits);
        }
        return merged;
    }
}
