package com.bank.search;

import com.bank.search.engine.SearchEngine;
import com.bank.search.index.Document;
import java.util.Set;
import java.util.logging.Logger;

public class SearchDemo {
    private static final Logger log = Logger.getLogger(SearchDemo.class.getName());

    public static void main(String[] args) {
        SearchEngine engine = new SearchEngine(3); // 3 primary shards

        // Index transaction audit documents for Rajesh and Priya.
        engine.index(new Document("TXN-1", "SAV2001", "International Wire transfer to London"));
        engine.index(new Document("TXN-2", "SAV2001", "Domestic NEFT transfer to Priya"));
        engine.index(new Document("TXN-3", "CUR3001", "international wire incoming from Dubai"));
        engine.index(new Document("TXN-4", "CUR3001", "ATM cash withdrawal Mumbai"));

        // Search is case/punctuation forgiving thanks to the analyzer.
        Set<String> hits = engine.search("International Wire");
        log.info(() -> "query 'International Wire' matched docs = " + hits);
    }
}
